-- 96 Photo Mode: P freezes the world (Time.set_scale(0)) and shows a
-- viewfinder; the arrows and - / = frame the shot on the wall clock; Space
-- hides the viewfinder and the gallery for one frame and takes it with
-- Screenshot.take - into a texture the gallery shows, and natively a PNG
-- under the save directory. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/96-photo-mode.scene"
local SLOTS, BIRDS, CLOUDS = 4, 6, 5

local captions = true
local e = {}
local photo = false
local wall = nil
local cx, cy, zoom = 0, 0, 1
local t = 0
local slot = 0
local shots = 0
local pending = nil      -- { id, slot }
local hidden_frames = 0
local filled = {}

local function show_gallery(v)
    for k = 0, SLOTS - 1 do
        UI.set_visible(e["Polaroid" .. k], v and filled[k] or false)
        UI.set_visible(e["Photo" .. k], v and filled[k] or false)
    end
end

local function set_photo(on)
    photo = on
    Time.set_scale(on and 0 or 1)
    UI.set_visible(e.Viewfinder, on)
    UI.set_visible(e.PhotoHint, on)
    -- toggle_ui_captions takes the state they are in and flips it.
    if captions then nav.toggle_ui_captions(on) end
    if not on then
        cx, cy, zoom = 0, 0, 1
        Transform.set_position(e.Camera, 0, 0)
        Camera.set_zoom(1)
    end
end

function init(entity)
    e.Camera = Entity.find_by_name("Camera")
    e.Viewfinder = Entity.find_by_name("Viewfinder")
    e.PhotoHint = Entity.find_by_name("PhotoHint")
    for k = 0, SLOTS - 1 do
        e["Polaroid" .. k] = Entity.find_by_name("Polaroid" .. k)
        e["Photo" .. k] = Entity.find_by_name("Photo" .. k)
        filled[k] = false
    end
    for i = 0, BIRDS - 1 do e["Bird" .. i] = Entity.find_by_name("Bird" .. i) end
    for i = 0, CLOUDS - 1 do e["Cloud" .. i] = Entity.find_by_name("Cloud" .. i) end
    UI.set_visible(e.Viewfinder, false)
    UI.set_visible(e.PhotoHint, false)
    show_gallery(true)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") and not photo then captions = nav.toggle_ui_captions(captions) end
    local now = Time.get_unix()
    local real = wall and math.min(0.1, now - wall) or 0
    wall = now

    -- The world: clouds drift, birds cross and flap. Frozen in photo mode,
    -- since `dt` is scaled.
    t = t + dt
    for i = 0, CLOUDS - 1 do
        local c = e["Cloud" .. i]
        local x, y = Transform.get_position(c)
        x = x + dt * (10 + i * 3)
        if x > 900 then x = -900 end
        Transform.set_position(c, x, y)
    end
    for i = 0, BIRDS - 1 do
        local b = e["Bird" .. i]
        local x, y = Transform.get_position(b)
        x = x + dt * (70 + i * 9)
        if x > 900 then x = -900 end
        Transform.set_position(b, x, y + math.sin(t * 2 + i) * dt * 10)
        Transform.set_scale(b, 1, 0.4 + 0.6 * math.abs(math.sin(t * 7 + i)))
    end

    if Input.is_key_just_pressed("P") then set_photo(not photo) end
    if photo then
        local pan = 300 * real / zoom
        if Input.is_key_pressed("Left") then cx = cx - pan end
        if Input.is_key_pressed("Right") then cx = cx + pan end
        if Input.is_key_pressed("Up") then cy = cy + pan end
        if Input.is_key_pressed("Down") then cy = cy - pan end
        if Input.is_key_pressed("Equal") then zoom = math.min(3, zoom * (1 + real)) end
        if Input.is_key_pressed("Minus") then zoom = math.max(1, zoom / (1 + real)) end
        cx = math.max(-160, math.min(160, cx))
        cy = math.max(-90, math.min(90, cy))
        Transform.set_position(e.Camera, cx, cy)
        Camera.set_zoom(zoom)
        if Input.is_key_just_pressed("Space") and not pending then
            -- The frame the photo is of shows only the world.
            UI.set_visible(e.Viewfinder, false)
            UI.set_visible(e.PhotoHint, false)
            show_gallery(false)
            pending = { id = Screenshot.take({ texture = "photos/overlook_" .. slot, file = "overlook_" .. shots,
                scale = 0.25 }), slot = slot }
            slot = (slot + 1) % SLOTS
            shots = shots + 1
            hidden_frames = 2
        end
    end
    if hidden_frames > 0 then
        hidden_frames = hidden_frames - 1
        if hidden_frames == 0 then
            UI.set_visible(e.Viewfinder, photo)
            UI.set_visible(e.PhotoHint, photo)
            show_gallery(true)
        end
    end
    if pending and Screenshot.ready(pending.id) then
        filled[pending.slot] = true
        pending = nil
        show_gallery(hidden_frames == 0)
    end
end
